                    [people]="people()" [rates]="rates()" [grades]="p.grades" [periods]="periods()"
                    [selected]="selectedClaims()" (selectedChange)="selectClaim($event.id, $event.on)"
                    (added)="claimAdded($event)" (saved)="claimSaved($event)" (changed)="claimSaved($event)"
